"""Small, careful client for the local order service (stdlib only).

Every request is logged to log.jsonl. Non-200 responses are logged in full so
odd behaviour can be inspected afterwards.
"""
import email.utils
import json
import os
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
WORK = os.path.dirname(os.path.abspath(__file__))
LOG_PATH = os.path.join(WORK, "log.jsonl")

DEFAULT_WAIT = 2.0
MAX_ATTEMPTS = 60


def _log(entry):
    with open(LOG_PATH, "a") as f:
        f.write(json.dumps(entry) + "\n")


def _parse_retry_after(headers, body_text):
    """Return seconds to wait, or None if the server gave no hint."""
    value = headers.get("Retry-After")
    if value is not None:
        value = value.strip()
        try:
            return max(0.0, float(value))
        except ValueError:
            try:
                when = email.utils.parsedate_to_datetime(value)
                return max(0.0, when.timestamp() - time.time())
            except (TypeError, ValueError):
                pass
    for name in ("X-RateLimit-Reset-After", "X-Retry-After"):
        if headers.get(name) is not None:
            try:
                return max(0.0, float(headers[name]))
            except ValueError:
                pass
    try:
        body = json.loads(body_text)
    except (ValueError, TypeError):
        return None
    if isinstance(body, dict):
        for key in ("retry_after", "retry_after_seconds", "retry_in", "wait", "wait_seconds"):
            if key in body:
                try:
                    return max(0.0, float(body[key]))
                except (TypeError, ValueError):
                    pass
    return None


class Client:
    def __init__(self):
        self.token = None
        self.stats = {"requests": 0, "token_fetches": 0, "by_status": {}, "slept": 0.0}

    def _raw(self, method, path, auth):
        headers = {"Accept": "application/json"}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        req = urllib.request.Request(BASE + path, method=method, headers=headers,
                                     data=b"" if method == "POST" else None)
        self.stats["requests"] += 1
        started = time.time()
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                status, hdrs, body = resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as e:
            status, hdrs, body = e.code, dict(e.headers), e.read()
        except (urllib.error.URLError, ConnectionError, TimeoutError, OSError) as e:
            status, hdrs, body = None, {}, repr(e).encode()
        text = body.decode("utf-8", errors="replace")
        key = str(status)
        self.stats["by_status"][key] = self.stats["by_status"].get(key, 0) + 1
        entry = {"t": started, "method": method, "path": path, "status": status,
                 "token": self.token if auth else None}
        if status != 200:
            entry["headers"] = hdrs
            entry["body"] = text[:2000]
        _log(entry)
        return status, hdrs, text

    def _sleep(self, seconds, why):
        _log({"t": time.time(), "sleep": seconds, "why": why})
        self.stats["slept"] += seconds
        time.sleep(seconds)

    def fetch_token(self):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            status, hdrs, text = self._raw("POST", "/token", auth=False)
            if status == 200:
                try:
                    tok = json.loads(text)["token"]
                except (ValueError, KeyError, TypeError):
                    tok = None
                if isinstance(tok, str) and tok:
                    self.token = tok
                    self.stats["token_fetches"] += 1
                    return tok
            wait = _parse_retry_after(hdrs, text)
            self._sleep(wait if wait is not None else DEFAULT_WAIT, f"token status={status}")
        raise RuntimeError("could not obtain a token")

    def get_json(self, path, validate, allow_404=False):
        """GET an authenticated path, retrying until `validate(obj)` accepts the body.

        Returns (obj, status). With allow_404, a 404 is returned as (None, 404).
        """
        if self.token is None:
            self.fetch_token()
        last = None
        for attempt in range(1, MAX_ATTEMPTS + 1):
            status, hdrs, text = self._raw("GET", path, auth=True)
            last = (status, text[:300])
            if status == 200:
                try:
                    obj = json.loads(text)
                except ValueError:
                    _log({"t": time.time(), "bad_json": path, "body": text[:2000]})
                    self._sleep(DEFAULT_WAIT / 2, "bad json")
                    continue
                problem = validate(obj)
                if problem is None:
                    return obj, 200
                _log({"t": time.time(), "invalid_body": path, "problem": problem, "body": text[:2000]})
                self._sleep(DEFAULT_WAIT / 2, "invalid body: " + problem)
                continue
            if status == 404 and allow_404:
                return None, 404
            if status in (401, 403):
                self.fetch_token()
                continue
            wait = _parse_retry_after(hdrs, text)
            if status == 429:
                self._sleep(wait if wait is not None else DEFAULT_WAIT, "429")
            else:
                self._sleep(wait if wait is not None else min(DEFAULT_WAIT * attempt, 10), f"status={status}")
        raise RuntimeError(f"giving up on {path}: last={last}")

