"""Fetch each distinct customer referenced by a saved orders pass, once, caching to disk.

Usage: python3 -I fetch_customers.py <orders_pass_dir> <customers_dir>
A 404 is re-requested a few times before being recorded as unknown.
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client  # noqa: E402

REQUIRED = {"id", "name", "region", "tier", "discount_pct"}


def make_validator(cid):
    def validate(obj):
        if not isinstance(obj, dict):
            return "not an object"
        if not REQUIRED <= set(obj):
            return f"missing keys {sorted(REQUIRED - set(obj))}"
        if obj["id"] != cid:
            return f"id mismatch: got {obj['id']!r}"
        return None
    return validate


def main(orders_dir, out_dir):
    os.makedirs(out_dir, exist_ok=True)
    ids = set()
    for f in os.listdir(orders_dir):
        if f.startswith("page_"):
            for it in json.load(open(os.path.join(orders_dir, f)))["items"]:
                ids.add(it["customer_id"])
    c = Client()
    not_found = {}
    for cid in sorted(ids):
        out = os.path.join(out_dir, f"{cid}.json")
        if os.path.exists(out):
            continue  # cached from an earlier run
        confirmations = 0
        while True:
            obj, status = c.get_json(f"/customers/{cid}", make_validator(cid), allow_404=True)
            if status == 200:
                with open(out, "w") as f:
                    json.dump(obj, f)
                break
            confirmations += 1
            if confirmations >= 3:
                not_found[cid] = confirmations
                break
    with open(os.path.join(out_dir, "_not_found.json"), "w") as f:
        json.dump(not_found, f)
    print("customers requested:", len(ids), "not found:", not_found)
    print("stats:", json.dumps(c.stats))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

